+// command's own `%w` prefix) sit on top of it. Both re-auth sentinels surface
+// as a *reauthError, so this single check covers ErrReauthRequired and
+// ErrNotLoggedIn.
+func ReauthMessage(err error) (string, bool) {
+	var re *reauthError
+	if errors.As(err, &re) {
+		return re.Error(), true
+	}
+	return "", false
+}
